package com.aoo.bcg.lobby;
import com.aoo.bcg.common.error.ErrorCodeCatalog;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import java.net.URI;import java.net.http.*;import java.time.Duration;import java.util.*;
public class LobbyHttpRoomAuthorityPort implements LobbyRoomCreateSaga.AuthorityPort,LobbyMembershipAuthorityPort{
 private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();private final URI base;private final String token;private final ObjectMapper json;
 public LobbyHttpRoomAuthorityPort(URI base,String token,ObjectMapper json){this.base=base;this.token=token;this.json=json;}
 public Map<String,Object>create(LobbyRoomCreateSaga.Command c){return call("create",body(c,c.stateVersion()));}public Map<String,Object>recover(LobbyRoomCreateSaga.Command c){return call("recover",body(c,c.stateVersion()));}public Map<String,Object>destroy(LobbyRoomCreateSaga.Command c,Map<String,Object>expectedLease){Map<String,Object>b=body(c,c.stateVersion());if(expectedLease==null)throw new IllegalStateException("ROOM_ORCHESTRATOR_DESTROY_IDENTITY_REQUIRED");for(String key:List.of("gameCode","roomInstanceId","lifecycleEpoch","fencingToken","stateVersion")){if(!expectedLease.containsKey(key))throw new IllegalStateException("ROOM_ORCHESTRATOR_DESTROY_IDENTITY_REQUIRED");b.put(key,expectedLease.get(key));}b.put("sessionId",c.requestId());b.put("reason","HALL_CREATE_COMPENSATION");return call("remove",b);}public void remove(LobbyRoomCreateSaga.Command c,long fence){throw new IllegalStateException("ROOM_AUTHORITY_TYPED_DESTROY_REQUIRED");}
 @Override public Map<String,Object>join(long roomId,long accountId,int seatNo,String playVersion,String requestId,String traceId,Map<String,Object>admission){Map<String,Object>b=new LinkedHashMap<>();b.put("roomId",roomId);b.put("accountId",accountId);b.put("seatNo",seatNo);b.put("playVersion",playVersion);b.put("requestId",requestId);b.put("traceId",traceId);b.put("admission",Map.copyOf(admission));return call("join",b);}
 @Override public Map<String,Object>leave(long roomId,long accountId,String playVersion,String requestId,String traceId,Map<String,Object>completeIdentity){if(completeIdentity==null||completeIdentity.isEmpty())throw new IllegalArgumentException("ROOM_ORCHESTRATOR_LEAVE_IDENTITY_REQUIRED");Map<String,Object>b=new LinkedHashMap<>(completeIdentity);b.put("roomId",roomId);b.put("accountId",accountId);b.put("playVersion",playVersion);b.put("requestId",requestId);b.put("idempotencyKey",requestId);b.put("traceId",traceId);return call("leave",Map.copyOf(b));}
 private static Map<String,Object>body(LobbyRoomCreateSaga.Command c,long fence){Map<String,Object>b=new LinkedHashMap<>();b.put("roomId",c.roomId());b.put("requestId",c.requestId());b.put("traceId",c.traceId());b.put("ownerId",c.accountId());b.put("gameId",c.gameId());b.put("playVersion",c.playVersion());b.put("fencingToken",fence);b.put("rules",c.rules());b.put("scope",c.scope().asMap());b.put("admission",c.admission());return b;}
 public static String canonicalCode(String wireCode,String message,int status){String direct=ErrorCodeCatalog.classify(wireCode,null);if(direct!=null)return direct;return ErrorCodeCatalog.classify(message,status>=500?"UPSTREAM_UNAVAILABLE":"INVALID_ENVELOPE");}
 private Map<String,Object>call(String action,Map<String,Object>b){RuntimeException last=null;for(int attempt=0;attempt<3;attempt++){try{var q=HttpRequest.newBuilder(base.resolve("/internal/v1/room-authority/"+action)).timeout(Duration.ofSeconds(8)).header("Content-Type","application/json").header("X-Aoo-Internal-Token",token).header("X-Trace-Id",String.valueOf(b.getOrDefault("traceId","authority"))).POST(HttpRequest.BodyPublishers.ofByteArray(json.writeValueAsBytes(b))).build();var r=http.send(q,HttpResponse.BodyHandlers.ofByteArray());if(r.statusCode()/100==2){Map<String,Object>envelope=json.readValue(r.body(),new TypeReference<>(){});Object data=envelope.get("data");if(data instanceof Map<?,?>map){@SuppressWarnings("unchecked")Map<String,Object>result=(Map<String,Object>)map;return Map.copyOf(result);}return Map.of();}Map<String,Object>error=json.readValue(r.body(),new TypeReference<>(){});String code=String.valueOf(error.getOrDefault("code","INTERNAL_AUTHORITY_FAILED"));String message=String.valueOf(error.getOrDefault("message","room authority rejected request"));if(r.statusCode()<500)throw new LobbyRoomAuthorityRejected(r.statusCode(),code,message);last=new LobbyRoomAuthorityRejected(503,code,message);}catch(LobbyRoomAuthorityRejected e){throw e;}catch(InterruptedException e){Thread.currentThread().interrupt();throw new LobbyRoomAuthorityRejected(503,"ROOM_AUTHORITY_UNAVAILABLE","room authority call interrupted",e);}catch(Exception e){last=new LobbyRoomAuthorityRejected(503,"ROOM_AUTHORITY_UNAVAILABLE","room authority unavailable: "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()),e);}if(attempt<2)try{Thread.sleep(100L<<attempt);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new LobbyRoomAuthorityRejected(503,"ROOM_AUTHORITY_UNAVAILABLE","room authority retry interrupted",e);}}throw last==null?new LobbyRoomAuthorityRejected(503,"ROOM_AUTHORITY_UNAVAILABLE","room authority unavailable"):last;}
}
